PRAGMA foreign_keys = ON;
CREATE TABLE storage_quota (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), reserved_bytes INTEGER NOT NULL CHECK (reserved_bytes >= 0));
INSERT INTO storage_quota (singleton, reserved_bytes) VALUES (1, 0);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL CHECK (count >= 0), expires_at INTEGER NOT NULL);
CREATE INDEX rate_limits_expiry ON rate_limits (expires_at);
CREATE TABLE transfers (id TEXT PRIMARY KEY CHECK (length(id) = 22), read_token_hash TEXT NOT NULL CHECK (length(read_token_hash) = 43), manage_token_hash TEXT NOT NULL CHECK (length(manage_token_hash) = 43 AND manage_token_hash != read_token_hash), encrypted_manifest TEXT NOT NULL, cipher_bytes INTEGER NOT NULL CHECK (cipher_bytes >= 28 AND cipher_bytes <= 10000066780), chunk_count INTEGER NOT NULL CHECK (chunk_count BETWEEN 1 AND 2385), state TEXT NOT NULL DEFAULT 'uploading' CHECK (state IN ('uploading', 'ready', 'revoked')), created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, upload_deadline INTEGER NOT NULL, reserved_bytes INTEGER NOT NULL CHECK (reserved_bytes IN (0, cipher_bytes)), create_ip_key TEXT NOT NULL, create_day_key TEXT NOT NULL, ip_rate_expires INTEGER NOT NULL, day_rate_expires INTEGER NOT NULL, cleanup_at INTEGER NOT NULL DEFAULT 0, CHECK (cipher_bytes - 28 * chunk_count BETWEEN 0 AND 10000000000), CHECK (chunk_count = MAX(1, (cipher_bytes - 28 * chunk_count + 4194303) / 4194304)));
CREATE INDEX transfers_cleanup ON transfers (state, cleanup_at, expires_at, upload_deadline);
CREATE TRIGGER transfer_reserve AFTER INSERT ON transfers BEGIN UPDATE storage_quota SET reserved_bytes = reserved_bytes + NEW.reserved_bytes WHERE singleton = 1; INSERT INTO rate_limits (key, count, expires_at) VALUES (NEW.create_ip_key, 1, NEW.ip_rate_expires) ON CONFLICT(key) DO UPDATE SET count = count + 1; INSERT INTO rate_limits (key, count, expires_at) VALUES (NEW.create_day_key, 1, NEW.day_rate_expires) ON CONFLICT(key) DO UPDATE SET count = count + 1; END;
CREATE TRIGGER transfer_release AFTER UPDATE OF reserved_bytes ON transfers BEGIN UPDATE storage_quota SET reserved_bytes = reserved_bytes + NEW.reserved_bytes - OLD.reserved_bytes WHERE singleton = 1; END;
CREATE TRIGGER transfer_no_rereserve BEFORE UPDATE OF reserved_bytes ON transfers WHEN NEW.reserved_bytes > OLD.reserved_bytes BEGIN SELECT RAISE(ABORT, 'reservation_is_monotonic'); END;
CREATE TABLE chunks (transfer_id TEXT NOT NULL REFERENCES transfers(id), chunk_index INTEGER NOT NULL CHECK (chunk_index BETWEEN 0 AND 2384), object_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL CHECK (state IN ('writing', 'stored', 'failed', 'fencing')), bytes INTEGER NOT NULL CHECK (bytes BETWEEN 28 AND 4194332), started_at INTEGER NOT NULL, cleanup_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (transfer_id, chunk_index));
CREATE INDEX chunks_cleanup ON chunks (transfer_id, cleanup_at, chunk_index);
CREATE TRIGGER chunk_bounds BEFORE INSERT ON chunks WHEN NEW.chunk_index >= (SELECT chunk_count FROM transfers WHERE id = NEW.transfer_id) BEGIN SELECT RAISE(ABORT, 'chunk_out_of_bounds'); END;
